/* Help · Operations, part 2 (W6): Fleet, Drivers, Routes & Tracking, Hubs, Proof of Delivery, Billing, Reports, AI. KK: titles; bodies fall back to RU with the marker. */

/* ---------------- Fleet ---------------- */
helpAdd({ key: 'fleet', group: 'ops', screen: 'fleet',
  title: HELP_NO('10', 'Автопарк', 'Fuhrpark', 'Fleet', 'Автопарк'), sub: HQ('Состояние, ТО, допуски', 'Zustand, Wartung, Zulassungen', 'Status, service, approvals', 'Күйі, ТО, рұқсаттар'),
  purpose: HQ('Состояние парка: тип и камеры, статус (свободен / в рейсе / сервис / критично), местоположение, пробег, ТО, калибровка датчика, страховки и налоги. Карточка ТС показывает документы со сроками и историю обслуживания.',
    'Zustand der Flotte: Typ und Kammern, Status (frei / im Einsatz / Service / kritisch), Standort, Laufleistung, Wartung, Sensorkalibrierung, Versicherungen und Steuern. Die Fahrzeugkarte zeigt Dokumente mit Fristen und die Wartungshistorie.',
    'Fleet status: type and chambers, status (available / in use / maintenance / critical), location, mileage, service, sensor calibration, insurance and taxes. The truck card shows documents with deadlines and the service history.'),
  who: HQ('Руководитель автопарка, диспетчер.', 'Fuhrparkleitung, Disponent.', 'Fleet manager, dispatcher.'),
  see: [
    HQ('KPI парка, фильтры (тип, статус, хаб), таблица ТС с индикатором здоровья и меткой «критично» при выходе температуры.', 'Flotten-KPI, Filter (Typ, Status, Hub), Fahrzeugtabelle mit Gesundheitsanzeige und Marke „kritisch“ bei Temperaturabweichung.', 'Fleet KPIs, filters (type, status, hub), truck table with a health indicator and a "critical" mark on a temperature excursion.')],
  howto: [{ t: HQ('Как понять, почему машина не может выйти в рейс', 'Verstehen, warum ein Fahrzeug nicht fahren darf', 'How to see why a truck cannot go', 'КҚ неге рейске шыға алмайтынын қалай түсінуге болады'), steps: [
    HQ('Статус «сервис» — открыта заявка в мастерскую (Диспетчерская доска → Партнёры); красные сроки ОГПО, налога или техосмотра блокируют выпуск.', 'Status „Service“ — offener Werkstattauftrag (Dispositionstafel → Partner); rote Fristen von Haftpflicht, Steuer oder Prüfung sperren die Freigabe.', 'Status "maintenance" — an open workshop request (Dispatch Board → Partners); red OGPO, tax or inspection deadlines block the release.'),
    HQ('Просроченная калибровка датчика блокирует фарма-рейсы (GDP): откалибруйте в Подтверждение доставки → Качество.', 'Abgelaufene Sensorkalibrierung sperrt Pharma-Fahrten (GDP): kalibrieren unter Lieferbestätigung → Qualität.', 'An expired sensor calibration blocks pharma loads (GDP): calibrate in Proof of Delivery → Quality.'),
  ] }],
  rules: [HQ('Допуск ТС к рейсу проверяется функцией совместимости: зона, паллето-места, занятость, поверка.', 'Die Zulassung zur Fahrt prüft die Verträglichkeitsfunktion: Zone, Palettenplätze, Verfügbarkeit, Kalibrierung.', 'Release of a truck for a load is checked by the compatibility function: zone, pallet places, availability, calibration.')],
  fr: 'FR-38, FR-50', related: ['fleet/registry', 'pod/quality', 'dispatch/partners'] });

helpAdd({ key: 'fleet/registry', group: 'ops', screen: 'fleet', tab: 'registry', visuals: ['truck'],
  title: HQ('Реестр ТС и обслуживание', 'Fahrzeugregister und Service', 'Vehicle registry and service', 'КҚ тізілімі және қызмет көрсету'), sub: HQ('виды, ввод в эксплуатацию, калибровка, гарантия, заявки на сервис', 'Ansichten, Inbetriebnahme, Kalibrierung, Garantie, Serviceaufträge', 'views, commissioning, calibration, warranty, service requests', 'көріністер, пайдалануға беру, калибрлеу, кепілдік, сервис өтінімдері'),
  purpose: HQ('Реестр машин (код, госномер, модель, грузоподъёмность, паллеты, камеры), чек-лист ввода в эксплуатацию, график калибровки логгеров и датчиков, прогноз окончания гарантии, заявки на сервис с ETA и стоимостью; сроки документов на 60 дней (меньше 14 дней — красный).',
    'Fahrzeugregister (Code, Kennzeichen, Modell, Nutzlast, Paletten, Kammern), Checkliste der Inbetriebnahme, Kalibrierplan der Logger und Sensoren, Prognose des Garantieendes, Serviceaufträge mit ETA und Kosten; Dokumentfristen 60 Tage (unter 14 Tagen rot).',
    'Vehicle register (code, plate, model, payload, pallets, chambers), commissioning checklist, calibration schedule of loggers and sensors, warranty-end forecast, service requests with ETA and cost; document deadlines for 60 days (below 14 days red).'),
  who: HQ('Руководитель автопарка (fleet:write), качество (калибровка).', 'Fuhrparkleitung (fleet:write), Qualität (Kalibrierung).', 'Fleet manager (fleet:write), quality (calibration).'),
  rules: [HQ('Изменение данных ТС версионируется и пишется в аудит; машина без завершённого чек-листа не выходит в рейс.', 'Änderungen an Fahrzeugdaten werden versioniert und auditiert; ein Fahrzeug ohne abgeschlossene Checkliste fährt nicht.', 'Changes to truck data are versioned and audited; a truck without a completed checklist does not go on a load.')],
  fr: 'FR-50, FR-118, FR-141, FR-157, FR-158', related: ['fleet', 'pod/quality', 'settings/reference'] });

/* ---------------- Drivers ---------------- */
helpAdd({ key: 'drivers', group: 'ops', screen: 'drivers',
  title: HQ('Водители', 'Fahrer', 'Drivers', 'Жүргізушілер'), sub: HQ('Compliance-реестр: РТО, документы, рейтинг', 'Compliance-Register: Lenkzeit, Dokumente, Bewertung', 'Compliance register: driving time, documents, rating', 'Compliance тізілімі: РТО, құжаттар, рейтинг'),
  purpose: HQ('Реестр водителей с акцентом на допуск: статус, риск по времени вождения (РТО), рейтинг, последний рейс, хаб, сроки прав и медосмотра. ИИН и телефон показаны замаскированно; отчёт о соответствии выгружается в CSV.',
    'Fahrerregister mit Schwerpunkt Zulassung: Status, Lenkzeitrisiko (RTO), Bewertung, letzte Fahrt, Hub, Fristen von Führerschein und Untersuchung. IIN und Telefon maskiert; der Compliance-Bericht wird als CSV exportiert.',
    'Driver register focused on eligibility: status, driving-time risk (RTO), rating, last load, hub, licence and medical deadlines. IIN and phone are masked; the compliance report exports as CSV.'),
  who: HQ('Руководитель автопарка, кадры, диспетчер.', 'Fuhrparkleitung, Personal, Disponent.', 'Fleet manager, HR, dispatcher.'),
  howto: [{ t: HQ('Как посмотреть персональные данные', 'Personendaten ansehen', 'How to view personal data', 'Жеке деректерді қалай көруге болады'), steps: [
    HQ('Только с правом pii:read: «Показать ПДн» в карточке водителя; каждый просмотр пишется в аудит — открывайте при необходимости.', 'Nur mit Recht pii:read: „Personendaten zeigen“ in der Fahrerkarte; jede Anzeige wird auditiert — nur bei Bedarf öffnen.', 'Only with pii:read: "Show personal data" in the driver card; every reveal is audited — open only when needed.')] }],
  rules: [HQ('Водитель с просроченными правами или медосмотром не назначается (совместимость); РТО ниже 4 ч даёт тревогу на Обзоре.', 'Ein Fahrer mit abgelaufenem Führerschein oder Untersuchung wird nicht zugewiesen (Verträglichkeit); RTO unter 4 h erzeugt einen Alarm auf der Übersicht.', 'A driver with an expired licence or medical is not assigned (compatibility); RTO below 4 h raises an alert on the Dashboard.')],
  fr: 'FR-08, FR-10', related: ['drivers/staff', 'drivers/app', 'data-protection'] });

helpAdd({ key: 'drivers/staff', group: 'ops', screen: 'drivers', tab: 'staff',
  title: HELP_NO('12', 'Персонал', 'Personal', 'Staff', 'Персонал'), sub: HQ('Доступность, отсутствия, время вождения 4,5 / 9 ч, штрафы', 'Verfügbarkeit, Abwesenheiten, Lenkzeit 4,5 / 9 h, Bußgelder', 'Availability, absences, driving time 4.5 / 9 h, fines', 'Қолжетімділік, болмау, жүргізу уақыты 4,5 / 9 сағ, айыппұлдар'),
  purpose: HQ('Где сейчас каждый водитель, кто может поехать в срочный рейс (часы вождения, ДОПОГ, категория), сроки документов, медосмотр, отсутствия и план на 14 дней; штрафы с автоматическим определением водителя по журналу использования ТС, скидкой 50 % и удержанием из зарплаты.',
    'Wo jeder Fahrer gerade ist, wer eine Eilfahrt übernehmen kann (Lenkzeit, ADR, Klasse), Dokumentfristen, Untersuchung, Abwesenheiten und Plan für 14 Tage; Bußgelder mit automatischer Fahrerzuordnung aus dem Fahrzeugnutzungsjournal, 50 % Rabatt und Lohnabzug.',
    'Where every driver is now, who can take an urgent trip (driving hours, ADR, licence class), document deadlines, medical, absences and a 14-day plan; fines with automatic driver attribution from the vehicle usage log, 50 % discount and pay deduction.'),
  who: HQ('Диспетчер, руководитель автопарка, финансы (fines:write).', 'Disponent, Fuhrparkleitung, Finanzen (fines:write).', 'Dispatcher, fleet manager, finance (fines:write).'),
  howto: [
    { t: HQ('Как назначить срочный рейс', 'Eine Eilfahrt zuweisen', 'How to assign an urgent trip', 'Шұғыл рейсті қалай тағайындауға болады'), steps: [
      HQ('Выберите хаб и при необходимости «нужен ДОПОГ» и «машина 7,5 / 12,5 т».', 'Hub wählen und ggf. „ADR nötig“ und „Fahrzeug 7,5 / 12,5 t“.', 'Choose the hub and if needed "ADR required" and "truck 7.5 / 12.5 t".'),
      HQ('Система показывает водителей (сейчас / позже / нет с причиной) и свободные машины; «Назначить: …» при наличии обоих.', 'Das System zeigt Fahrer (jetzt / später / nein mit Grund) und freie Fahrzeuge; „Zuweisen: …“ wenn beides da ist.', 'The system shows drivers (now / later / no with reason) and free trucks; "Assign: …" when both exist.')] },
    { t: HQ('Как обработать штраф', 'Ein Bußgeld bearbeiten', 'How to process a fine', 'Айыппұлды қалай өңдеуге болады'), steps: [
      HQ('«Импорт постановлений» или регистрация во «Входящих» (SMS 1414, Kaspi, eGov); водитель определён по журналу ТС в момент нарушения.', '„Bescheide importieren“ oder Erfassung im „Eingang“ (SMS 1414, Kaspi, eGov); der Fahrer ergibt sich aus dem Fahrzeugjournal zur Tatzeit.', '"Import notices" or registration in the "Inbox" (SMS 1414, Kaspi, eGov); the driver is attributed from the vehicle log at the time of the offence.'),
      HQ('«Оплатить со скидкой 50 %» (7 дней с даты нарушения), «Удержать из зарплаты» или «Оспорить»; «Уведомить водителя» отправляет сообщение в приложение.', '„Mit 50 % Rabatt zahlen“ (7 Tage ab Tatdatum), „Vom Lohn abziehen“ oder „Einspruch“; „Fahrer benachrichtigen“ sendet eine Nachricht in die App.', '"Pay with 50 % discount" (7 days from the offence), "Deduct from pay" or "Dispute"; "Notify driver" sends a message to the app.')] },
  ],
  rules: [
    HQ('Для срочного рейса нужно ≥ 6 ч остатка вождения из дневной нормы 9 ч; перерыв 45 мин после 4,5 ч; категория B не подходит для 7,5 / 12,5 т.', 'Für eine Eilfahrt sind ≥ 6 h Restlenkzeit von 9 h nötig; Pause 45 min nach 4,5 h; Klasse B passt nicht für 7,5 / 12,5 t.', 'An urgent trip needs ≥ 6 h remaining of the 9 h daily limit; 45 min break after 4.5 h; licence class B does not fit 7.5 / 12.5 t.'),
    HQ('Действия по штрафам — только по неоплаченному штрафу (fines:write); назначение — drivers:write.', 'Aktionen bei Bußgeldern nur für offene Bußgelder (fines:write); Zuweisen — drivers:write.', 'Fine actions only on unpaid fines (fines:write); assigning needs drivers:write.')],
  fr: 'FR-07, FR-08, FR-10, FR-46, FR-55, FR-114, FR-120, FR-122, FR-123', related: ['drivers', 'drivers/app', 'reports'] });

helpAdd({ key: 'drivers/app', group: 'portals', screen: 'drivers', tab: 'app', visuals: ['driver'],
  title: HELP_NO('13', 'Приложение водителя', 'Fahrer-App', 'Driver app', 'Жүргізуші қосымшасы'), sub: HQ('Смартфон водителя в рейсе: смена, маршрут, точка, возвраты, топливо, SOS', 'Smartphone des Fahrers auf Tour: Schicht, Route, Stopp, Retouren, Kraftstoff, SOS', 'Driver smartphone on a trip: shift, route, stop, returns, fuel, SOS', 'Жолдағы жүргізуші смартфоны: ауысым, маршрут, нүкте, қайтарулар, отын, SOS'),
  purpose: HQ('Вид телефона в рамке: предрейсовый чек-лист, подпись путевого листа, точка доставки с ePOD (прибытие → температура → фото → подпись получателя), сканирование SSCC, термохрон, исключения (повреждение, недостача, отказ), возвраты, заправка, сообщения, штрафы, SOS и закрытие смены. Работает офлайн: события встают в очередь и уходят при появлении связи.',
    'Telefonansicht im Rahmen: Abfahrtskontrolle, Signatur des Fahrauftrags, Stopp mit ePOD (Ankunft → Temperatur → Foto → Unterschrift des Empfängers), SSCC-Scan, Thermochron, Ausnahmen (Schaden, Fehlmenge, Ablehnung), Retouren, Tanken, Nachrichten, Bußgelder, SOS und Schichtende. Funktioniert offline: Ereignisse werden gepuffert und bei Netz gesendet.',
    'Phone view in a frame: pre-trip checklist, trip-sheet signature, delivery stop with ePOD (arrival → temperature → photo → recipient signature), SSCC scan, thermochron, exceptions (damage, shortage, refusal), returns, fuel, messages, fines, SOS and shift end. Works offline: events are queued and sent when the network returns.'),
  who: HQ('Водитель (driver:app); диспетчер видит ленту событий.', 'Fahrer (driver:app); der Disponent sieht den Ereignis-Feed.', 'Driver (driver:app); the dispatcher sees the event feed.'),
  howto: [
    { t: HQ('Как начать смену', 'Die Schicht beginnen', 'How to start a shift', 'Ауысымды қалай бастауға болады'), steps: [
      HQ('Вкладка «Смена»: отметьте все пункты чек-листа; пока калибровка логгера просрочена, пункт заблокирован.', 'Reiter „Schicht“: alle Punkte der Checkliste abhaken; solange die Logger-Kalibrierung abgelaufen ist, ist der Punkt gesperrt.', 'Tab "Shift": tick all checklist items; while the logger calibration is expired the item is locked.'),
      HQ('Подпишите путевой лист — только при полном чек-листе и только один раз.', 'Fahrauftrag signieren — nur bei vollständiger Checkliste und nur einmal.', 'Sign the trip sheet — only with a complete checklist and only once.')] },
    { t: HQ('Как сдать груз на точке (ePOD)', 'Ware am Stopp übergeben (ePOD)', 'How to deliver at a stop (ePOD)', 'Жүкті нүктеде қалай тапсыруға болады (ePOD)'), steps: [
      HQ('Вкладка «Точка»: прибытие → температура → фото → подпись получателя; шаги нельзя пропустить; отсканируйте места SSCC и считайте термохрон.', 'Reiter „Stopp“: Ankunft → Temperatur → Foto → Unterschrift; Schritte nicht überspringbar; SSCC scannen und Thermochron auslesen.', 'Tab "Stop": arrival → temperature → photo → signature; steps cannot be skipped; scan the SSCC packages and read the thermochron.'),
      HQ('При повреждении, недостаче или отказе — кнопка исключения: уходит в «Качество» и диспетчеру. После 4-го шага ePOD отправлен.', 'Bei Schaden, Fehlmenge oder Ablehnung — Ausnahme-Knopf: geht an „Qualität“ und Disponent. Nach Schritt 4 ist der ePOD gesendet.', 'For damage, shortage or refusal — the exception button: goes to "Quality" and the dispatcher. After step 4 the ePOD is sent.')] },
    { t: HQ('Как работать без связи', 'Ohne Netz arbeiten', 'How to work without network', 'Байланыссыз қалай жұмыс істеуге болады'), steps: [
      HQ('Без сети события в очереди; в мёртвой зоне критичные события и контрольный сигнал каждые 30 минут уходят подписанной SMS (канал OL1).', 'Ohne Netz werden Ereignisse gepuffert; im Funkloch gehen kritische Ereignisse und ein Lebenszeichen alle 30 Minuten als signierte SMS (Kanal OL1).', 'Without network events are queued; in a dead zone critical events and a heartbeat every 30 minutes go as a signed SMS (channel OL1).')] },
  ],
  rules: [
    HQ('Закрытие смены необратимо: часы уходят в «Персонал», отмеченный дефект — заявкой в сервис; SOS создаёт инцидент как тревожная кнопка.', 'Schichtende ist endgültig: Stunden gehen an „Personal“, ein markierter Defekt als Serviceauftrag; SOS erzeugt einen Vorfall wie die Notfalltaste.', 'Ending the shift is irreversible: hours go to "Staff", a marked defect becomes a service request; SOS creates an incident like the panic button.'),
    HQ('Диспетчер и склад не подписывают и не закрывают ничего от имени водителя.', 'Disponent und Lager signieren oder schließen nichts im Namen des Fahrers.', 'Dispatchers and warehouse sign or close nothing in the driver’s name.')],
  fr: 'FR-52 … FR-67, FR-70', related: ['dispatch/express', 'routes/sec', 'routes/coverage', 'pod'] });

/* ---------------- Routes & Tracking ---------------- */
helpAdd({ key: 'routes', group: 'ops', screen: 'routes', tab: 'map',
  title: HQ('Маршруты и трекинг — карта', 'Routen & Tracking — Karte', 'Routes & Tracking — map', 'Маршруттар және трекинг — карта'), sub: HQ('Активные маршруты, ETA, статус', 'Aktive Routen, ETA, Status', 'Active routes, ETA, status', 'Белсенді маршруттар, ETA, күй'),
  purpose: HQ('Карта сети и таблица активных маршрутов: прогресс, ETA, температура и статус каждого рейса; клик по маркеру или строке открывает карточку рейса с точками маршрута. Остальные вкладки раздела: температура, погода, безопасность, покрытие связи, линии и тарифы.',
    'Netzkarte und Tabelle der aktiven Routen: Fortschritt, ETA, Temperatur und Status jeder Fahrt; Klick auf Marker oder Zeile öffnet die Fahrtkarte mit Routenpunkten. Weitere Registerkarten: Temperatur, Wetter, Sicherheit, Netzabdeckung, Linien & Tarife.',
    'Network map and table of active routes: progress, ETA, temperature and status of every load; a click on a marker or row opens the load card with route stops. Other tabs of the section: temperature, weather, security, coverage, lines & tariffs.'),
  who: HQ('Диспетчер, служба безопасности.', 'Disponent, Sicherheit.', 'Dispatcher, security.'),
  rules: [HQ('Фильтр статуса маршрута и масштаб карты; маркер окрашен по температурному состоянию.', 'Filter für den Routenstatus und Kartenmaßstab; der Marker ist nach Temperaturzustand gefärbt.', 'Route status filter and map zoom; the marker is coloured by temperature state.')],
  related: ['routes/temp', 'routes/wx', 'routes/sec', 'routes/coverage', 'routes/lines'] });

helpAdd({ key: 'routes/temp', group: 'ops', screen: 'routes', tab: 'temp', visuals: ['coldchain'],
  title: HELP_NO('05', 'Температура', 'Temperatur', 'Temperature', 'Температура'), sub: HQ('Камеры и наружная температура, термохроны, пассивная цепь', 'Kammern und Außentemperatur, Thermochrone, passive Kühlkette', 'Chambers and outside temperature, thermochrons, passive chain', 'Камералар мен сыртқы температура, термохрондар, пассивті тізбек'),
  purpose: HQ('Живые температуры камер по каждой машине, история замеров, состояние агрегата, двери и логгера, правила тревог холодовой цепи и импорт термохронов при приёмке. Для изотермов без агрегата — пассивная холодовая цепь: термоконтейнеры с хладоэлементами и логгерами.',
    'Live-Temperaturen der Kammern je Fahrzeug, Messverlauf, Zustand von Aggregat, Tür und Logger, Alarmregeln der Kühlkette und Import der Thermochrone bei Annahme. Für Isothermen ohne Aggregat — passive Kühlkette: Thermocontainer mit Kühlakkus und Loggern.',
    'Live chamber temperatures per vehicle, reading history, unit, door and logger status, cold-chain alarm rules and thermochron import at receipt. For isothermal bodies without a unit — the passive cold chain: thermo containers with cool packs and loggers.'),
  who: HQ('Диспетчер, качество, склад.', 'Disponent, Qualität, Lager.', 'Dispatcher, quality, warehouse.'),
  see: [HQ('График: допустимые диапазоны зон (−18, 0…+4, +2…+8, +15…+25 °C); карточки машин; журнал показаний (неизменяемый).', 'Diagramm: zulässige Zonenbereiche (−18, 0…+4, +2…+8, +15…+25 °C); Fahrzeugkarten; Messwertjournal (unveränderlich).', 'Chart: allowed zone ranges (−18, 0…+4, +2…+8, +15…+25 °C); vehicle cards; readings log (append-only).')],
  howto: [{ t: HQ('Как импортировать термохрон', 'Ein Thermochron importieren', 'How to import a thermochron', 'Термохронды қалай импорттауға болады'), steps: [
    HQ('После приёмки найдите строку термохрона со статусом «файл ожидается» и нажмите «Импорт» — появятся min / max / среднее.', 'Nach der Annahme die Thermochron-Zeile mit „Datei erwartet“ suchen und „Import“ drücken — Min / Max / Mittel erscheinen.', 'After receipt find the thermochron row "file expected" and press "Import" — min / max / average appear.'),
    HQ('Если были минуты вне диапазона, в «Качестве» автоматически создаётся отклонение — продолжайте там.', 'Gab es Minuten außerhalb des Bereichs, wird in „Qualität“ automatisch eine Abweichung angelegt — dort weiterarbeiten.', 'If there were minutes out of range a deviation is created in "Quality" automatically — continue there.')] }],
  rules: [
    HQ('Камера вне диапазона зоны — критично; 15–25 °C вне диапазона — риск; наружная ниже −25 °C — критично; дверь открыта дольше 3 минут — риск.', 'Kammer außerhalb der Zone — kritisch; 15–25 °C außerhalb — Risiko; außen unter −25 °C — kritisch; Tür länger als 3 Minuten offen — Risiko.', 'Chamber out of its zone range — critical; 15–25 °C out of range — risk; outside below −25 °C — critical; door open longer than 3 minutes — risk.'),
    HQ('Изотермы без агрегата: товар 2–8 °C только в термоконтейнерах с логгерами, не дольше 48 ч в пути; импорт термохрона — temperature:write.', 'Isotherme ohne Aggregat: 2–8 °C-Ware nur in Thermocontainern mit Loggern, höchstens 48 h unterwegs; Thermochron-Import — temperature:write.', 'Isothermal bodies without a unit: 2–8 °C goods only in thermo containers with loggers, at most 48 h in transit; thermochron import needs temperature:write.')],
  fr: 'FR-39, FR-40', related: ['pod/quality', 'dashboard/alarms', 'receiving'] });

helpAdd({ key: 'routes/wx', group: 'ops', screen: 'routes', tab: 'wx',
  title: HELP_NO('06', 'Погода 3–7 дней', 'Wetter 3–7 Tage', 'Weather 3–7 days', 'Ауа райы 3–7 күн'), sub: HQ('Прогноз, штормовые предупреждения, правило −45 °C', 'Prognose, Unwetterwarnungen, −45 °C-Regel', 'Forecast, storm warnings, −45 °C rule', 'Болжам, дауыл ескертулері, −45 °C ережесі'),
  purpose: HQ('Прогноз по городам сети, окрашенный по риску для рейса, закрытия трасс, штормовые предупреждения Казгидромета, погодный риск каждого рейса и пороги тревог. Критичная погода блокирует шлюз «Маршрут одобрен по погоде».',
    'Prognose für die Netzstädte, nach Fahrtrisiko eingefärbt, Straßensperrungen, Unwetterwarnungen von Kazhydromet, Wetterrisiko je Fahrt und Alarmschwellen. Kritisches Wetter sperrt das Gate „Route wetterseitig freigegeben“.',
    'Forecast for the network cities coloured by trip risk, road closures, Kazhydromet storm warnings, weather risk per load and alarm thresholds. Critical weather blocks the gate "Route cleared for weather".'),
  who: HQ('Диспетчер, планировщик.', 'Disponent, Planer.', 'Dispatcher, planner.'),
  howto: [{ t: HQ('Как снять закрытие дороги досрочно', 'Eine Straßensperrung vorzeitig aufheben', 'How to lift a road closure early', 'Жол жабылуын мерзімінен бұрын қалай алуға болады'), steps: [
    HQ('Найдите сообщение в блоке дорог и погоды и нажмите «Снять досрочно» — тревога рейса пропадает, сообщение во «Входящих» выполнено (trips:write).', 'Meldung im Block Straßen und Wetter suchen und „Vorzeitig aufheben“ drücken — der Touralarm verschwindet, die Meldung im „Eingang“ ist erledigt (trips:write).', 'Find the message in the roads and weather block and press "Lift early" — the trip alarm disappears and the inbox message is done (trips:write).')] }],
  rules: [
    HQ('Риск рейса = худший уровень по городам маршрута в день выезда и на следующий день; при −45 °C и ниже рейс не выпускается.', 'Fahrtrisiko = schlechteste Stufe der Routenstädte am Abfahrtstag und am Folgetag; bei −45 °C und darunter wird keine Fahrt freigegeben.', 'Trip risk = worst level over the route cities on the departure day and the next day; at −45 °C and below no trip is released.'),
    HQ('В макете прогноз смоделирован; в работе — Казгидромет / Open-Meteo и КазАвтоЖол.', 'Im Mock-up ist die Prognose simuliert; im Betrieb Kazhydromet / Open-Meteo und KazAvtoZhol.', 'In the mock-up the forecast is simulated; in operation Kazhydromet / Open-Meteo and KazAvtoZhol.')],
  fr: 'FR-16, FR-42, FR-43', related: ['dispatch', 'orders/docs', 'dashboard/inbox', 'dispatch/planning'] });

helpAdd({ key: 'routes/sec', group: 'ops', screen: 'routes', tab: 'sec',
  title: HELP_NO('07', 'Безопасность', 'Sicherheit', 'Security', 'Қауіпсіздік'), sub: HQ('Инциденты, геозоны, ДОПОГ, сухой лёд', 'Vorfälle, Geozonen, ADR, Trockeneis', 'Incidents, geofences, ADR, dry ice', 'Оқиғалар, геоаймақтар, ДОПОГ, құрғақ мұз'),
  purpose: HQ('Обработка инцидентов с эскалацией и журналом действий, события геозон, режим труда и ДОПОГ водителей, двери и пломбы, тест тревожной кнопки, контакты охраны в один клик.',
    'Bearbeitung von Vorfällen mit Eskalation und Aktionsprotokoll, Geozonen-Ereignisse, Lenkzeiten und ADR der Fahrer, Türen und Plomben, Test der Notfalltaste, Wachdienst-Kontakte per Klick.',
    'Incident handling with escalation and action log, geofence events, driving time and ADR of drivers, doors and seals, panic button test, one-click guard contacts.'),
  who: HQ('Служба безопасности, диспетчер.', 'Sicherheitsdienst, Disponent.', 'Security officer, dispatcher.'),
  howto: [{ t: HQ('Как обработать инцидент', 'Einen Vorfall bearbeiten', 'How to handle an incident', 'Оқиғаны қалай өңдеуге болады'), steps: [
    HQ('Новый инцидент: «Принять» → при необходимости «Эскалировать» → после решения «Закрыть»; каждый шаг пишется в аудит (alarms:write).', 'Neuer Vorfall: „Annehmen“ → bei Bedarf „Eskalieren“ → nach der Lösung „Schließen“; jeder Schritt wird auditiert (alarms:write).', 'New incident: "Acknowledge" → if needed "Escalate" → when solved "Close"; every step is audited (alarms:write).'),
    HQ('«Тест тревожной кнопки» создаёт критичный инцидент; SOS из приложения водителя — такой же.', '„Test Notfalltaste“ erzeugt einen kritischen Vorfall; SOS aus der Fahrer-App ebenso.', '"Test panic button" creates a critical incident; SOS from the driver app does the same.')] }],
  rules: [HQ('Порядок статусов: новый → принят → эскалирован → закрыт; закрытый нельзя открыть снова; хранится не больше 50 инцидентов SOS.', 'Statusfolge: neu → angenommen → eskaliert → geschlossen; Geschlossenes lässt sich nicht wieder öffnen; höchstens 50 SOS-Vorfälle werden gehalten.', 'Status order: new → acknowledged → escalated → closed; a closed incident cannot be reopened; at most 50 SOS incidents are kept.')],
  fr: 'FR-109, FR-111', related: ['dashboard/alarms', 'drivers/app', 'routes/coverage', 'settings/oncall'] });

helpAdd({ key: 'routes/coverage', group: 'ops', screen: 'routes', tab: 'coverage', visuals: ['coverage'],
  title: HQ('Покрытие связи и SMS-резерв', 'Netzabdeckung und SMS-Reserve', 'Network coverage and SMS fallback', 'Байланыс жабыны және SMS-резерв'), sub: HQ('Мёртвые зоны, последний контакт, SMS-канал OL1', 'Funklöcher, letzter Kontakt, SMS-Kanal OL1', 'Dead zones, last contact, SMS channel OL1', 'Өлі аймақтар, соңғы байланыс, OL1 SMS-арнасы'),
  purpose: HQ('На длинных степных участках машина может часами быть без мобильных данных, хотя 2G ещё работает. Вкладка показывает схему покрытия трасс, окна без связи по каждому рейсу, последний контакт с машинами и SMS-канал OL1, по которому критичные события доходят без интернета.',
    'Auf langen Steppenabschnitten kann ein Fahrzeug stundenlang ohne mobile Daten sein, obwohl 2G noch funktioniert. Die Registerkarte zeigt das Abdeckungsschema, die Funklöcher je Fahrt, den letzten Kontakt und den SMS-Kanal OL1, über den kritische Ereignisse auch ohne Internet ankommen.',
    'On long steppe stretches a truck can be without mobile data for hours while 2G still works. The tab shows the coverage schematic, the offline windows per load, the last contact with the vehicles and the SMS channel OL1, which carries critical events even without internet.'),
  who: HQ('Диспетчер, служба безопасности; водитель — SMS-режим.', 'Disponent, Sicherheit; Fahrer — SMS-Modus.', 'Dispatcher, security; driver — SMS mode.'),
  howto: [{ t: HQ('Как действовать при потере связи с машиной', 'Vorgehen bei Kontaktverlust', 'What to do when a vehicle loses contact', 'Көлікпен байланыс үзілгенде не істеу керек'), steps: [
    HQ('Нет данных > 30 минут: в ожидаемой мёртвой зоне — «вне покрытия, SMS-канал активен» (внимание); иначе — риск, тревога идёт во «Входящие» и на «Безопасность».', 'Über 30 Minuten keine Daten: im erwarteten Funkloch — „außerhalb der Abdeckung, SMS-Kanal aktiv“ (Hinweis); sonst Risiko, der Alarm geht in den „Eingang“ und zu „Sicherheit“.', 'No data for over 30 minutes: in an expected dead zone — "out of coverage, SMS channel active" (attention); otherwise risk, the alarm goes to the "Inbox" and "Security".'),
    HQ('Посмотрите последние SMS машины; при необходимости выберите инструкцию (ждать, позвонить, проверить температуру, остановиться) и «Отправить SMS водителю».', 'Letzte SMS ansehen; bei Bedarf Anweisung wählen (warten, anrufen, Temperatur prüfen, anhalten) und „SMS an Fahrer senden“.', 'Check the last SMS of the vehicle; if needed pick an instruction (wait, call, check temperature, stop) and "Send SMS to driver".')] }],
  rules: [HQ('Одна SMS до 160 латинских символов, подписана ключом машины (HMAC), с порядковым номером; только коды и температура, без персональных данных; не больше 3 инструкций на машину за 10 минут.', 'Eine SMS bis 160 lateinische Zeichen, mit Fahrzeugschlüssel signiert (HMAC) und nummeriert; nur Codes und Temperatur, keine Personendaten; höchstens 3 Anweisungen je Fahrzeug in 10 Minuten.', 'One SMS of up to 160 Latin characters, signed with the vehicle key (HMAC) and numbered; only codes and temperature, no personal data; at most 3 instructions per vehicle in 10 minutes.')],
  fr: 'FR-109 … FR-111', related: ['drivers/app', 'routes/sec', 'dispatch'] });

helpAdd({ key: 'routes/lines', group: 'ops', screen: 'routes', tab: 'lines',
  title: HQ('Линии и тарифы', 'Linien & Tarife', 'Lines & tariffs', 'Желілер және тарифтер'), sub: HQ('расписания, отправления, исключения, тарифы', 'Fahrpläne, Abfahrten, Ausnahmen, Tarife', 'schedules, departures, exceptions, tariffs', 'кестелер, жөнелтулер, ерекшеліктер, тарифтер'),
  purpose: HQ('Регулярные линии (дни, время выезда, вместимость, камеры, закрытие приёма) — из них портал строит слоты; тарифы по хабу и режиму — из них считается цена; ТС на линии и исключения расписания (праздники РК).',
    'Linienverkehre (Tage, Abfahrt, Kapazität, Kammern, Annahmeschluss) — daraus baut das Portal Termine; Tarife je Hub und Klasse — daraus wird der Preis berechnet; Fahrzeuge je Linie und Fahrplanausnahmen (Feiertage der RK).',
    'Regular lines (days, departure time, capacity, chambers, cut-off) — the portal builds slots from them; tariffs per hub and class — the price is computed from them; vehicles per line and schedule exceptions (Kazakh holidays).'),
  who: HQ('Руководитель логистики (planning:admin), диспетчер (просмотр).', 'Logistikleitung (planning:admin), Disponent (Ansicht).', 'Head of logistics (planning:admin), dispatcher (view).'),
  howto: [{ t: HQ('Как изменить тариф', 'Einen Tarif ändern', 'How to change a tariff', 'Тарифті қалай өзгертуге болады'), steps: [
    HQ('«✎» в строке: измените базу, ставку ₸ / паллета · км и минимум, «Сохранить» — версия пишется в аудит.', '„✎“ in der Zeile: Grundpreis, Satz ₸ / Palette · km und Minimum ändern, „Speichern“ — die Version wird auditiert.', '"✎" in the row: change base fee, rate ₸ / pallet · km and minimum, "Save" — the version is audited.')] }],
  rules: [HQ('Цена = max(минимум; база + паллеты × км × ставка), округление до 100 ₸, плюс НДС 16 %.', 'Preis = max(Minimum; Grundpreis + Paletten × km × Satz), auf 100 ₸ gerundet, zzgl. 16 % MwSt.', 'Price = max(minimum; base + pallets × km × rate), rounded to 100 ₸, plus 16 % VAT.')],
  fr: 'FR-96, FR-97, FR-155', related: ['orders/bookings', 'portal/book', 'settings/reference'] });

/* ---------------- Hubs ---------------- */
helpAdd({ key: 'hubs', group: 'ops', screen: 'hubs', tab: 'hubs',
  title: HQ('Хабы и склады', 'Hubs & Lager', 'Warehouses & Hubs', 'Хабтар мен қоймалар'), sub: HQ('Загрузка хабов, доки, ёмкость по зонам', 'Hub-Auslastung, Tore, Kapazität je Zone', 'Hub utilisation, docks, capacity by zone', 'Хабтардың жүктемесі, қақпалар, аймақтар бойынша сыйымдылық'),
  purpose: HQ('Хабы Астана, Алматы, Караганда, Шымкент: загрузка по температурным зонам (красный ≥ 90 %), карточки и карта, лицензии GDP, обслуживание доков. Переключатель «карточки / карта».',
    'Hubs Astana, Almaty, Karaganda, Schymkent: Auslastung je Temperaturzone (rot ≥ 90 %), Karten und Karte, GDP-Lizenzen, Torwartung. Umschalter „Karten / Karte“.',
    'Hubs Astana, Almaty, Karaganda, Shymkent: utilisation by temperature zone (red ≥ 90 %), cards and map, GDP licences, dock maintenance. Toggle "cards / map".'),
  who: HQ('Склад, руководитель логистики.', 'Lager, Logistikleitung.', 'Warehouse, head of logistics.'),
  rules: [HQ('Хаб на обслуживании недоступен для новых приёмок; пустые зоны помечены как свободные.', 'Ein Hub in Wartung nimmt keine neuen Annahmen an; leere Zonen gelten als frei.', 'A hub under maintenance takes no new receipts; empty zones are shown as free.')],
  related: ['receiving', 'dispatch/planning'] });

helpAdd({ key: 'receiving', group: 'ops', screen: 'hubs', tab: 'recv',
  title: HQ('Приёмка на хабе', 'Wareneingang am Hub', 'Receiving at the hub', 'Хабта қабылдау'), sub: HQ('ворота, разгрузка, исключения, термохрон', 'Tor, Entladung, Ausnahmen, Thermochron', 'gate, unloading, exceptions, thermochron', 'қақпа, түсіру, ерекшеліктер, термохрон'),
  purpose: HQ('Входящие рейсы на хабе назначения: прибытие на ворота, разгрузка, сверка мест, исключения (повреждение, недостача, температура) и считывание термохрона. Рейс, перешедший в «в пути», сам создаёт задачу приёмки; значок на вкладке — рейсы на воротах.',
    'Ankommende Fahrten am Zielhub: Ankunft am Tor, Entladung, Packstückabgleich, Ausnahmen (Schaden, Fehlmenge, Temperatur) und Auslesen des Thermochrons. Eine Fahrt, die „unterwegs“ geht, legt die Annahmeaufgabe selbst an; der Zähler zeigt Fahrten am Tor.',
    'Incoming loads at the destination hub: arrival at the gate, unloading, package reconciliation, exceptions (damage, shortage, temperature) and reading the thermochron. A load that goes "in transit" creates its receiving job itself; the badge shows loads at the gate.'),
  who: HQ('Склад хаба.', 'Hub-Lager.', 'Hub warehouse.'),
  rules: [HQ('Исключение при приёмке открывает отклонение в «Качестве»; после приёмки рейс попадает в очередь POD.', 'Eine Ausnahme beim Wareneingang öffnet eine Abweichung in „Qualität“; nach der Annahme kommt die Fahrt in die POD-Warteschlange.', 'An exception at receipt opens a deviation in "Quality"; after receipt the load enters the POD queue.')],
  related: ['routes/temp', 'pod', 'pod/quality'] });

/* ---------------- Proof of Delivery ---------------- */
helpAdd({ key: 'pod', group: 'ops', screen: 'pod', tab: 'queue',
  title: HQ('Подтверждение доставки — очередь POD', 'Lieferbestätigung — POD-Warteschlange', 'Proof of Delivery — POD queue', 'Жеткізуді растау — POD кезегі'), sub: HQ('загрузка, проверка и подтверждение документов доставки', 'Upload, Prüfung und Bestätigung der Lieferdokumente', 'upload, review and approval of delivery documents', 'жеткізу құжаттарын жүктеу, тексеру және растау'),
  purpose: HQ('Очередь доставленных рейсов: документы POD (ТТН, акт приёма-передачи, фото, данные логгера) загружаются, проверяются и подтверждаются; подтверждённый POD создаёт счёт (раздел «Счета и ЭСФ»). Отклонённый POD возвращается на доработку.',
    'Warteschlange gelieferter Fahrten: POD-Dokumente (TTN, Übergabeprotokoll, Foto, Loggerdaten) werden hochgeladen, geprüft und bestätigt; ein bestätigter POD erzeugt die Rechnung (Bereich „Rechnungen & ESF“). Ein abgelehnter POD geht zur Nachbesserung zurück.',
    'Queue of delivered loads: POD documents (TTN, handover act, photo, logger data) are uploaded, reviewed and approved; an approved POD creates the invoice (section "Billing & Invoices"). A rejected POD goes back for rework.'),
  who: HQ('Диспетчер, финансы; клиент и партнёр загружают свои документы через портал.', 'Disponent, Finanzen; Kunde und Partner laden ihre Dokumente über das Portal hoch.', 'Dispatcher, finance; customer and partner upload their documents through the portal.'),
  howto: [{ t: HQ('Как подтвердить POD', 'Einen POD bestätigen', 'How to approve a POD', 'POD қалай растауға болады'), steps: [
    HQ('Откройте рейс «Ожидает загрузки» → загрузите ТТН, акт, фото (и данные логгера для холодовых грузов).', 'Fahrt „Upload ausstehend“ öffnen → TTN, Übergabeprotokoll, Foto (und Loggerdaten bei Kühlware) hochladen.', 'Open a load "Pending upload" → upload TTN, act, photo (and logger data for cold goods).'),
    HQ('«Отправить на проверку» → проверка → «Подтвердить» (создаётся счёт) или «Отклонить» с причиной.', '„Zur Prüfung senden“ → Prüfung → „Bestätigen“ (Rechnung entsteht) oder „Ablehnen“ mit Grund.', '"Submit for review" → review → "Approve" (an invoice is created) or "Reject" with a reason.')] }],
  rules: [HQ('Пока комплект документов не полон, подтвердить POD нельзя; массовое подтверждение пропускает неполные.', 'Solange der Dokumentensatz unvollständig ist, kann kein POD bestätigt werden; die Sammelbestätigung überspringt unvollständige.', 'An incomplete document set cannot be approved; the bulk approval skips incomplete ones.')],
  related: ['pod/quality', 'billing', 'receiving'] });

helpAdd({ key: 'pod/quality', group: 'ops', screen: 'pod', tab: 'quality', visuals: ['coldchain'],
  title: HELP_NO('09', 'Отклонения и качество', 'Abweichungen & Qualität', 'Deviations & quality', 'Ауытқулар және сапа'), sub: HQ('Отклонения, CAPA, карантин, калибровка, GDP', 'Abweichungen, CAPA, Quarantäne, Kalibrierung, GDP', 'Deviations, CAPA, quarantine, calibration, GDP', 'Ауытқулар, CAPA, карантин, калибрлеу, GDP'),
  purpose: HQ('Отклонения холодовой цепи и партнёров: процесс из 7 шагов с решением ответственного за качество (допустить или карантин), CAPA и реестр калибровки логгеров и датчиков (GDP). Рейс, перешедший в «проблему», открывает отклонение сам; затронутые заказы встают на карантин.',
    'Abweichungen der Kühlkette und von Partnern: 7-Schritte-Prozess mit Entscheidung des Qualitätsverantwortlichen (freigeben oder Quarantäne), CAPA und Kalibrierregister der Logger und Sensoren (GDP). Eine Fahrt, die auf „Problem“ geht, öffnet die Abweichung selbst; betroffene Aufträge kommen in Quarantäne.',
    'Cold-chain and partner deviations: a 7-step process with the quality manager decision (release or quarantine), CAPA and the calibration register of loggers and sensors (GDP). A load that turns "problem" opens the deviation itself; affected orders go into quarantine.'),
  who: HQ('Ответственный за качество, склад (quality:write).', 'Qualitätsverantwortlicher, Lager (quality:write).', 'Quality manager, warehouse (quality:write).'),
  see: [HQ('Процесс: 1 Тревога · 2 Диспетчер · 3 СБ · 4 Решение QA · 5 Допущен / заблокирован · 6 Клиент уведомлён · 7 CAPA оформлена.', 'Prozess: 1 Alarm · 2 Disponent · 3 Sicherheit · 4 QA-Entscheidung · 5 Freigegeben / gesperrt · 6 Kunde informiert · 7 CAPA erfasst.', 'Process: 1 Alarm · 2 Dispatcher · 3 Security · 4 QA decision · 5 Released / blocked · 6 Customer notified · 7 CAPA issued.')],
  howto: [{ t: HQ('Как оформить отклонение и CAPA', 'Abweichung und CAPA bearbeiten', 'How to process a deviation and CAPA', 'Ауытқуды және CAPA-ны қалай рәсімдеуге болады'), steps: [
    HQ('Выберите отклонение; «Выполнить шаг» по мере прохождения шагов 1–3.', 'Abweichung wählen; „Schritt ausführen“, während die Schritte 1–3 erledigt werden.', 'Select the deviation; "Complete step" as steps 1–3 are done.'),
    HQ('Шаг 4: «Допустить товар» или «Заблокировать (карантин)» — журнал фиксирует решение; затем уведомление клиента и CAPA (шаг 7).', 'Schritt 4: „Ware freigeben“ oder „Sperren (Quarantäne)“ — das Protokoll hält die Entscheidung fest; dann Kundeninformation und CAPA (Schritt 7).', 'Step 4: "Release goods" or "Block (quarantine)" — the log records the decision; then customer notice and CAPA (step 7).'),
    HQ('Калибровка: у просроченного датчика «Откалибровать» — после этого фарма-рейсы снова доступны.', 'Kalibrierung: beim abgelaufenen Sensor „Kalibrieren“ — danach sind Pharma-Fahrten wieder möglich.', 'Calibration: on an expired sensor press "Calibrate" — pharma loads become available again.')] }],
  rules: [
    HQ('Шаги нельзя пропустить; решение возможно только на шаге 4.', 'Schritte lassen sich nicht überspringen; die Entscheidung geht nur in Schritt 4.', 'Steps cannot be skipped; the decision is only possible at step 4.'),
    HQ('Заблокированного партнёра разблокируют только после закрытия его CAPA; просроченная калибровка блокирует выпуск фарма-рейса.', 'Ein gesperrter Partner wird erst nach Abschluss seiner CAPA entsperrt; abgelaufene Kalibrierung sperrt die Freigabe einer Pharma-Fahrt.', 'A blocked partner is unblocked only after its CAPA is closed; an expired calibration blocks the release of a pharma load.')],
  fr: 'FR-11, FR-25, FR-40, FR-103, FR-117', related: ['routes/temp', 'dispatch/partners', 'billing/insurance', 'fleet/registry'] });

