helpAdd({ key: 'billing', group: 'ops', screen: 'billing', tab: 'inv',
  title: HQ('Счета и ЭСФ', 'Rechnungen & ESF', 'Billing & Invoices', 'Шоттар және ЭШФ'), sub: HQ('счета, НДС 12 %, ЭСФ, споры', 'Rechnungen, MwSt. 12 %, ESF, Streitfälle', 'invoices, VAT 12 %, ESF, disputes', 'шоттар, ҚҚС 12 %, ЭШФ, даулар'),
  purpose: HQ('Счета по подтверждённым POD: сумма без НДС, НДС, итог, статус оплаты, статус ЭСФ (нет / выписана / подтверждена) и споры клиента по температуре. ЭСФ выписывается из счёта и подтверждается в ИС ЭСФ (в макете — имитация).',
    'Rechnungen zu bestätigten POD: Nettobetrag, MwSt., Summe, Zahlungsstatus, ESF-Status (keine / ausgestellt / bestätigt) und Kundenstreit zur Temperatur. Die ESF wird aus der Rechnung ausgestellt und im IS ESF bestätigt (im Mock-up simuliert).',
    'Invoices for approved PODs: net amount, VAT, total, payment status, ESF status (none / issued / confirmed) and customer temperature disputes. The ESF is issued from the invoice and confirmed in IS ESF (simulated in the mock-up).'),
  who: HQ('Финансы, руководитель логистики; аудитор (чтение).', 'Finanzen, Logistikleitung; Auditor (lesend).', 'Finance, head of logistics; auditor (read).'),
  rules: [HQ('Платёж без подтверждённой ЭСФ и ЭСФ при открытом споре отмечаются как аномалии (AI-ассистент); сроки ЕСУТД — в статье «Сроки».', 'Zahlung ohne bestätigte ESF und ESF bei offenem Streit werden als Anomalien markiert (KI-Assistent); ESUTD-Fristen im Artikel „Fristen“.', 'Payment without a confirmed ESF and ESF with an open dispute are flagged as anomalies (AI assistant); ESUTD deadlines are in the "Deadlines" article.')],
  related: ['billing/cost', 'pod', 'orders/docs', 'ai', 'deadlines'] });

helpAdd({ key: 'billing/cost', group: 'ops', screen: 'billing', tab: 'cost',
  title: HELP_NO('16', 'Затраты', 'Kosten', 'Costs', 'Шығындар'), sub: HQ('модель снизу вверх, реестр фактов, свой или внешний (2 подписи), себестоимость + 5 %', 'Bottom-up-Modell, Ist-Register, Eigen oder extern (2 Unterschriften), Kosten + 5 %', 'bottom-up model, actuals register, own vs external (2 signatures), cost + 5 %', 'төменнен жоғары модель, факт тізілімі, өз немесе сыртқы (2 қол), өзіндік құн + 5 %'),
  purpose: HQ('Затраты собственного парка снизу вверх (дизель, сервис и простои, страховки и налоги, водители) против аутсорсинга, реестр фактических затрат по категориям и решение «свой рейс или внешний перевозчик» с утверждением двумя подписями; для цены — себестоимость + 5 %.',
    'Laufende Kosten der eigenen Flotte von unten (Diesel, Werkstatt und Ausfall, Versicherung und Steuern, Fahrer) gegen Outsourcing, Ist-Kostenregister nach Kategorie und die Entscheidung „eigene Fahrt oder externer Frachtführer“ mit zwei Unterschriften; für den Preis — Kosten + 5 %.',
    'Bottom-up running cost of the own fleet (diesel, workshop and downtime, insurance and taxes, drivers) against outsourcing, a register of actual costs by category and the decision "own trip or external carrier" with two-signature approval; for pricing — cost + 5 %.'),
  who: HQ('Финансовый контролёр, руководитель логистики (costs:approve), аудитор.', 'Finanzcontroller, Logistikleitung (costs:approve), Auditor.', 'Financial controller, head of logistics (costs:approve), auditor.'),
  howto: [{ t: HQ('Как согласовать затраты (2 подписи)', 'Kosten freigeben (2 Unterschriften)', 'How to approve costs (2 signatures)', 'Шығындарды қалай келісуге болады (2 қол)'), steps: [
    HQ('Если разница между своим рейсом и перевозчиком больше 50 %, нужны две подписи: руководитель логистики подписывает свою роль.', 'Liegt der Unterschied zwischen eigener Fahrt und Frachtführer über 50 %, sind zwei Unterschriften nötig: die Logistikleitung signiert ihre Rolle.', 'If the gap between own trip and carrier is above 50 %, two signatures are needed: the head of logistics signs their role.'),
    HQ('Финансовый контролёр — другой пользователь — подписывает вторую роль; подпись видна с именем и временем.', 'Der Finanzcontroller — ein anderer Benutzer — signiert die zweite Rolle; die Unterschrift zeigt Name und Zeit.', 'The financial controller — a different user — signs the second role; each signature shows name and time.')] }],
  rules: [HQ('Каждую роль подписывают один раз, один пользователь не ставит обе подписи (принцип четырёх глаз); позиции «допущение» нужно подтвердить.', 'Jede Rolle nur einmal; ein Benutzer kann nicht beide Unterschriften leisten (Vier-Augen-Prinzip); Positionen „Annahme“ müssen bestätigt werden.', 'Each role can be signed once; one user cannot give both signatures (four-eyes principle); items marked "assumption" must be confirmed.')],
  fr: 'FR-46, FR-47, FR-125', related: ['fleet', 'baseline', 'dispatch/partners', 'roles'] });

helpAdd({ key: 'billing/insurance', group: 'ops', screen: 'billing', tab: 'insurance',
  title: HQ('Страхование грузов', 'Transportversicherung', 'Cargo insurance', 'Жүк сақтандыру'), sub: HQ('полис · сертификат на отправку · страховые случаи по отклонениям', 'Police · Zertifikat je Sendung · Schadenfälle aus Abweichungen', 'policy · certificate per shipment · claims from deviations', 'полис · жөнелтімге сертификат · ауытқулар бойынша сақтандыру жағдайлары'),
  purpose: HQ('Карточка страховщика и генерального полиса (вымышленная плановая запись), страховой сертификат (ОБРАЗЕЦ) на каждую застрахованную отправку и страховые случаи: убыток заявляется по отклонению температуры, сумма не выше объявленной стоимости. Статусы: открыт → подан → урегулирован или отклонён.',
    'Karte des Versicherers und der Generalpolice (fiktiver Planwert), Versicherungszertifikat (MUSTER) je versicherte Sendung und Schadenfälle: ein Schaden wird aus einer Temperaturabweichung gemeldet, Betrag höchstens der deklarierte Wert. Status: offen → eingereicht → reguliert oder abgelehnt.',
    'Card of the insurer and the open cover (a fictitious planning entry), insurance certificate (SAMPLE) per insured shipment and claims: a claim is opened from a temperature deviation, amount up to the declared value. Status: open → submitted → settled or rejected.'),
  who: HQ('Качество, склад, администратор (quality:write).', 'Qualität, Lager, Administrator (quality:write).', 'Quality, warehouse, administrator (quality:write).'),
  howto: [{ t: HQ('Как заявить убыток', 'Einen Schaden melden', 'How to open a claim', 'Залалды қалай мәлімдеуге болады'), steps: [
    HQ('Из отклонения застрахованной отправки нажмите «Страховой случай» (или введите номера вручную); сумма не выше объявленной стоимости, описание без имён.', 'Aus der Abweichung der versicherten Sendung „Schadenfall“ (oder Nummern eintippen); Betrag höchstens der deklarierte Wert, Beschreibung ohne Namen.', 'From the deviation of the insured shipment press "Insurance claim" (or type the numbers); amount up to the declared value, description without names.'),
    HQ('«Открыть страховой случай» → «Подать страховщику» → «Урегулирован» или «Отклонён»; каждый шаг просит подтверждение и комментарий.', '„Schadenfall anlegen“ → „Beim Versicherer einreichen“ → „Reguliert“ oder „Abgelehnt“; jeder Schritt fragt Bestätigung und Vermerk ab.', '"Open claim" → "Submit to insurer" → "Settled" or "Rejected"; every step asks for a confirmation and a note.')] }],
  rules: [HQ('Один открытый случай на заказ и отклонение; бронирование должно быть застраховано (иначе отказ); запись страховщика заменить данными договора перед запуском.', 'Ein offener Fall je Auftrag und Abweichung; die Buchung muss versichert sein (sonst Ablehnung); den Versichererdatensatz vor dem Start durch Vertragsdaten ersetzen.', 'One open claim per order and deviation; the booking must be insured (otherwise refused); replace the insurer entry with contract data before go-live.')],
  fr: 'FR-28, FR-153', related: ['pod/quality', 'orders/bookings', 'portal/my'] });

