helpAdd({ key: 'reports', group: 'ops', screen: 'reports',
  title: HELP_NO('15', 'Отчёты', 'Berichte', 'Reports', 'Есептер'), sub: HQ('карточки отчётов, OTIF, загрузка, доля экспресса, стоимость на кг, экспорт', 'Berichtskarten, OTIF, Auslastung, Express-Anteil, Kosten je kg, Export', 'report cards, OTIF, load factor, express share, cost per kg, export', 'есеп карталары, OTIF, жүктеме, экспресс үлесі, кг құны, экспорт'),
  purpose: HQ('Каталог отчётов по группам с фильтром периода и деталями в ящике: OTIF, коэффициент загрузки, доля экспресса, стоимость на кг, температурное соответствие, отчёт по водителям; импорт штрафов; выгрузка PDF / CSV / JSON и сводка GDP. Отчёт «экспресс × температура» показывает пересечение.',
    'Berichtskatalog in Gruppen mit Zeitraumfilter und Details in der Schublade: OTIF, Auslastungsgrad, Express-Anteil, Kosten je kg, Temperatur-Compliance, Fahrerbericht; Bußgeldimport; Export PDF / CSV / JSON und GDP-Zusammenfassung. Der Bericht „Express × Temperatur“ zeigt die Überschneidung.',
    'Report catalogue in groups with a period filter and details in the drawer: OTIF, load factor, express share, cost per kg, temperature compliance, driver report; fines import; PDF / CSV / JSON export and a GDP summary. The "express × temperature" report shows the crossing.'),
  who: HQ('Руководство, финансы, качество, аудитор.', 'Leitung, Finanzen, Qualität, Auditor.', 'Management, finance, quality, auditor.'),
  rules: [HQ('Цель OTIF по SLA ≥ 95 %; выгрузки персональных данных нет, детали содержат только номера.', 'OTIF-Ziel laut SLA ≥ 95 %; kein Export von Personendaten, Details enthalten nur Nummern.', 'OTIF SLA target ≥ 95 %; no personal-data export, details contain numbers only.')],
  fr: 'FR-07, FR-64, FR-126', related: ['drivers/staff', 'dispatch/express', 'billing/cost', 'ai'] });

helpAdd({ key: 'ai', group: 'ops', screen: 'ai',
  title: HQ('AI-ассистент', 'KI-Assistent', 'AI Ops Assistant', 'AI-көмекші'), sub: HQ('рекомендации, аномалии, пороги уверенности, аудит решений', 'Empfehlungen, Anomalien, Konfidenzschwellen, Entscheidungsprotokoll', 'recommendations, anomalies, confidence thresholds, decision audit', 'ұсыныстар, ауытқулар, сенімділік шектері, шешімдер аудиті'),
  purpose: HQ('Ассистент операций: предлагает пару водитель + ТС, ранние предупреждения по температуре, поиск утечек затрат и аномалии в счетах. Каждая рекомендация показывает уверенность и причину; принять или отклонить решает человек, решение пишется в аудит. Правила в макете детерминированные, внешнего ИИ нет.',
    'Betriebsassistent: schlägt Paare Fahrer + Fahrzeug vor, warnt früh bei Temperatur, findet Kostenlecks und Anomalien in Rechnungen. Jede Empfehlung zeigt Konfidenz und Grund; der Mensch nimmt an oder lehnt ab, die Entscheidung wird auditiert. Die Regeln im Mock-up sind deterministisch, es gibt keine externe KI.',
    'Operations assistant: proposes driver + truck pairs, early temperature warnings, finds cost leaks and invoice anomalies. Every recommendation shows confidence and a reason; a person accepts or rejects and the decision is audited. The rules in the mock-up are deterministic, there is no external AI.'),
  who: HQ('Диспетчер, финансы, руководство.', 'Disponent, Finanzen, Leitung.', 'Dispatcher, finance, management.'),
  rules: [HQ('Пороги уверенности и автодействия настраиваются в Настройки → AI; данные не покидают Казахстан, внешних ИИ-сервисов нет.', 'Konfidenzschwellen und Auto-Aktionen unter Einstellungen → KI; Daten verlassen Kasachstan nicht, es gibt keine externen KI-Dienste.', 'Confidence thresholds and auto-actions are set in Settings → AI; data does not leave Kazakhstan, there are no external AI services.')],
  related: ['settings', 'billing', 'data-protection'] });
